head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Bengali:wght@300;400;500;600;700;800&family=Hind+Siliguri:wght@300;400;500;600;700&display=swap');

:root {
  --background: hsl(210 20% 98%);
  --foreground: hsl(220 20% 10%);
  --surface: hsl(0 0% 100%);
  --card: hsl(0 0% 100%);
  --border: hsl(214 20% 88%);
  --header-bg: hsl(220 25% 12%);
  --header-foreground: hsl(0 0% 95%);
  --primary: hsl(215 80% 35%);
  --primary-light: hsl(215 75% 92%);
  --primary-text: hsl(215 80% 30%);
  --news: hsl(215 80% 35%);
  --news-bg: hsl(215 75% 92%);
  --news-text: hsl(215 80% 30%);
  --blog: hsl(152 55% 38%);
  --blog-bg: hsl(152 50% 90%);
  --blog-text: hsl(152 55% 25%);
  --directory: hsl(270 40% 50%);
  --directory-bg: hsl(270 40% 92%);
  --directory-text: hsl(270 40% 30%);
  --muted: hsl(210 15% 93%);
  --muted-foreground: hsl(220 10% 45%);
  --divider-accent: hsl(30 80% 55%);
  --destructive: hsl(0 84% 60%);
  --shadow-sm: 0 1px 3px rgba(21,37,65,0.04);
  --shadow: 0 18px 40px rgba(21,37,65,0.08);
  --shadow-lg: 0 20px 34px rgba(22,37,66,0.08);
  --radius: 18px;
  --radius-sm: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background:
    radial-gradient(circle at top right, rgba(37,99,235,0.08), transparent 28%),
    radial-gradient(circle at bottom left, rgba(124,58,237,0.07), transparent 24%),
    var(--background);
  color: var(--foreground);
  font-family: 'Hind Siliguri', sans-serif;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--primary); text-decoration: none; transition: color .2s; }
a:hover { color: var(--news); }
img { max-width: 100%; border-radius: 16px; display: block; }

.page-shell { min-height: 100vh; display: flex; flex-direction: column; }
.container { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }

/* ============ HEADER ============ */
.topbar {
  background: var(--header-bg);
  color: var(--header-foreground);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 0;
}
.brand-block h1, .brand-block h2, .brand-block .title {
  margin: 0;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.4rem, 3vw, 1.8rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--header-foreground);
}
.brand-block .description {
  margin-top: 4px;
  color: rgba(255,255,255,0.72);
  font-size: 0.88rem;
}
.quick-search {
  flex: 1;
  max-width: 420px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  padding: 10px 18px 10px 40px;
  color: rgba(255,255,255,0.5);
  font-size: 0.9rem;
  position: relative;
}
.quick-search::before {
  content: '🔍';
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.85rem;
}

/* ============ NAV WITH MEGA MENU ============ */
.nav-wrap {
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 50;
}
.nav-bar {
  display: flex;
  align-items: center;
  gap: 2px;
}
.nav-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 16px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--foreground);
  background: none;
  border: none;
  cursor: pointer;
  border-radius: 10px;
  transition: all .2s;
  white-space: nowrap;
}
.nav-btn:hover { background: var(--muted); }
.nav-btn.active { background: var(--primary); color: white; }
.nav-btn .arrow {
  display: inline-block;
  transition: transform .2s;
  font-size: 0.7rem;
}
.nav-btn.active .arrow { transform: rotate(180deg); }
.nav-link {
  display: inline-flex;
  align-items: center;
  padding: 12px 16px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--foreground);
  border-radius: 10px;
  transition: all .2s;
  text-decoration: none;
}
.nav-link:hover { background: var(--muted); color: var(--foreground); text-decoration: none; }

/* Mega Menu Dropdown */
.mega-menu {
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  background: var(--card);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  z-index: 60;
  display: none;
  animation: slideDown .25s ease-out;
}
.mega-menu.open { display: block; }
@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}
.mega-menu-inner {
  display: flex;
  gap: 16px;
  padding: 16px 0;
  max-height: 70vh;
  overflow: hidden;
}
.mega-menu-letters {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px 12px 4px 0;
  border-right: 1px solid var(--border);
  overflow-y: auto;
  flex-shrink: 0;
}
.mega-letter-btn {
  width: 32px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: none;
  border-radius: 8px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.88rem;
  cursor: pointer;
  color: var(--foreground);
  transition: all .15s;
}
.mega-letter-btn:hover { background: var(--primary); color: white; }
.mega-letter-btn.disabled { color: var(--muted-foreground); opacity: 0.35; cursor: default; }
.mega-letter-btn.disabled:hover { background: none; color: var(--muted-foreground); }

.mega-menu-search {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--card);
  z-index: 5;
}
.mega-search-input {
  flex: 1;
  max-width: 360px;
  padding: 8px 14px 8px 36px;
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 0.88rem;
  font-family: 'Hind Siliguri', sans-serif;
  background: var(--background);
  position: relative;
}
.mega-search-input:focus { outline: none; border-color: var(--primary); }
.mega-close-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: var(--muted);
  border-radius: 8px;
  cursor: pointer;
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .2s;
}
.mega-close-btn:hover { background: var(--border); }

.mega-menu-content {
  flex: 1;
  overflow-y: auto;
  padding-right: 8px;
}
.mega-cat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}
.mega-cat-group-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 0.9rem;
  margin-bottom: 6px;
}
.mega-cat-group-letter.news { background: var(--news-bg); color: var(--news-text); }
.mega-cat-group-letter.blog { background: var(--blog-bg); color: var(--blog-text); }
.mega-cat-group-letter.directory { background: var(--directory-bg); color: var(--directory-text); }

.mega-cat-link {
  display: block;
  padding: 3px 0;
  font-size: 0.88rem;
  color: var(--foreground);
  opacity: 0.8;
  transition: all .15s;
  text-decoration: none;
}
.mega-cat-link:hover { color: var(--primary); opacity: 1; text-decoration: underline; }

.mega-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.15);
  z-index: 45;
  display: none;
}
.mega-overlay.open { display: block; }

/* ============ 3-COLUMN LAYOUT ============ */
.three-col {
  display: grid;
  grid-template-columns: 28% 1fr 20%;
  gap: 16px;
  padding: 20px 0;
}

/* ============ LEFT SIDEBAR (Tabbed) ============ */
.left-sidebar {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 60px;
  align-self: start;
}
.sidebar-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
}
.sidebar-tab {
  flex: 1;
  padding: 10px 8px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
  text-align: center;
  border: none;
  cursor: pointer;
  background: none;
  color: var(--muted-foreground);
  transition: all .2s;
}
.sidebar-tab:hover { background: var(--muted); color: var(--foreground); }
.sidebar-tab.active { background: var(--primary); color: white; }
.sidebar-post-list { list-style: none; }
.sidebar-post-item {
  display: flex;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  transition: background .15s;
  text-decoration: none;
  color: var(--foreground);
}
.sidebar-post-item:hover { background: var(--muted); text-decoration: none; color: var(--foreground); }
.sidebar-post-num {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--muted-foreground);
  opacity: 0.5;
  margin-top: 2px;
  flex-shrink: 0;
  width: 20px;
}
.sidebar-post-title {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 0.88rem;
  font-weight: 500;
  line-height: 1.4;
}
.sidebar-empty {
  padding: 16px;
  text-align: center;
  color: var(--muted-foreground);
  font-size: 0.88rem;
}

/* ============ RIGHT SIDEBAR ============ */
.right-sidebar {
  position: sticky;
  top: 60px;
  align-self: start;
}
.sidebar-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow-sm);
  margin-bottom: 16px;
}

/* ============ HERO / FEATURE SLIDER ============ */
.hero-slider {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  margin-bottom: 16px;
}
.hero-slider-inner {
  position: relative;
  min-height: 220px;
}
.hero-slide {
  display: none;
  padding: 28px;
  background: linear-gradient(135deg, rgba(26,82,153,0.06), rgba(18,125,81,0.05)), rgba(255,255,255,0.94);
}
.hero-slide.active { display: block; animation: fadeInUp .4s ease-out; }
.hero-slide .hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--news-bg);
  color: var(--news);
  font-weight: 700;
  font-size: 0.85rem;
  margin-bottom: 12px;
}
.hero-slide h3 {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.4rem, 3vw, 2rem);
  line-height: 1.2;
  margin-bottom: 8px;
}
.hero-slide h3 a { color: var(--foreground); }
.hero-slide h3 a:hover { color: var(--primary); }
.hero-slide p { color: var(--muted-foreground); font-size: 0.92rem; }
.hero-dots {
  display: flex;
  justify-content: center;
  gap: 6px;
  padding: 12px;
}
.hero-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  border: none;
  background: var(--border);
  cursor: pointer;
  transition: all .2s;
}
.hero-dot.active { background: var(--primary); width: 24px; }

/* ============ SECTION DIVIDER ============ */
.section-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
}
.section-divider::before, .section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--divider-accent), transparent);
  opacity: 0.4;
}
.section-divider-text {
  color: var(--divider-accent);
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 1.1rem;
  white-space: nowrap;
}
.section-title {
  margin: 0 0 14px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: 1.2rem;
  font-weight: 800;
}

/* ============ POSTS ============ */
.post, .post-outer {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-bottom: 16px;
  transition: transform .2s, box-shadow .2s;
}
.post:hover, .post-outer:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}
h2.post-title, .post-title {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  line-height: 1.25;
  margin: 0 0 10px;
}
.post-title a { color: var(--foreground); }
.post-title a:hover { color: var(--primary); }
.post-meta, .byline {
  color: var(--muted-foreground);
  font-size: 0.88rem;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}
.post-meta-item { display: inline-flex; align-items: center; gap: 4px; }
.post-body, .post-snippet, .entry-content {
  color: var(--foreground);
  font-size: 0.95rem;
  line-height: 1.8;
}
.post-body img, .entry-content img { border-radius: 16px; margin: 14px 0; }

/* ============ CATEGORY TAGS ============ */
.tag-news { display: inline-block; background: var(--news-bg); color: var(--news-text); font-size: 0.75rem; padding: 2px 10px; border-radius: 999px; font-weight: 600; }
.tag-blog { display: inline-block; background: var(--blog-bg); color: var(--blog-text); font-size: 0.75rem; padding: 2px 10px; border-radius: 999px; font-weight: 600; }
.tag-directory { display: inline-block; background: var(--directory-bg); color: var(--directory-text); font-size: 0.75rem; padding: 2px 10px; border-radius: 999px; font-weight: 600; }

/* ============ SHARE BUTTONS ============ */
.share-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}
.share-bar-label { font-family: 'Noto Sans Bengali', sans-serif; font-weight: 700; font-size: 0.85rem; color: var(--muted-foreground); margin-right: 2px; }
.share-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; border-radius: 8px;
  border: 1px solid var(--border); background: var(--surface);
  color: var(--muted-foreground); font-size: 0.88rem;
  cursor: pointer; transition: all .2s; text-decoration: none;
}
.share-btn:hover { text-decoration: none; }
.share-btn-fb:hover { background: var(--news-bg); color: var(--news); border-color: var(--news-bg); }
.share-btn-tw:hover { background: hsl(200 80% 92%); color: hsl(200 80% 40%); }
.share-btn-copy:hover { background: var(--muted); color: var(--foreground); }
.share-btn-bookmark { margin-left: auto; width: auto; padding: 0 12px; gap: 6px; font-weight: 600; font-size: 0.8rem; }
.share-btn-bookmark:hover { background: var(--primary-light); color: var(--primary); border-color: var(--primary); }

/* ============ BUSINESS CARDS ============ */
.bcard-section {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  margin-top: 16px;
}
.bcard-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 14px;
  margin-top: 14px;
}
.bcard-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 16px;
  background: var(--surface);
  transition: transform .2s, box-shadow .2s;
}
.bcard-item:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
.bcard-name {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: 2px;
}
.bcard-title { font-size: 0.82rem; color: var(--muted-foreground); margin-bottom: 6px; }
.bcard-org { font-size: 0.85rem; color: var(--primary); font-weight: 600; margin-bottom: 8px; }
.bcard-info { font-size: 0.82rem; color: var(--muted-foreground); line-height: 1.6; }
.bcard-info span { display: block; }

/* ============ COMMENTS ============ */
.comments-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  margin-top: 16px;
}
.comments-section h4 {
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 1.05rem;
  margin-bottom: 14px;
}
.comment-item { padding: 12px 0; border-bottom: 1px solid var(--border); }
.comment-item:last-child { border-bottom: 0; }
.comment-author { font-weight: 700; font-size: 0.9rem; }
.comment-date { font-size: 0.78rem; color: var(--muted-foreground); margin-left: 8px; }
.comment-body { font-size: 0.92rem; margin-top: 4px; line-height: 1.7; }

/* ============ MASONRY GRID ============ */
.masonry-section { padding: 12px 0 32px; }
.masonry-grid { columns: 4; column-gap: 14px; }
.masonry-item {
  break-inside: avoid;
  margin-bottom: 14px;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  transition: transform .3s, box-shadow .3s;
}
.masonry-item:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
.masonry-item img { width: 100%; border-radius: 0; display: block; }
.masonry-item-content { padding: 12px; }
.masonry-item-title { font-family: 'Noto Sans Bengali', sans-serif; font-weight: 700; font-size: 0.9rem; line-height: 1.35; margin-bottom: 4px; }
.masonry-item-title a { color: var(--foreground); }
.masonry-item-title a:hover { color: var(--primary); }
.masonry-item-excerpt { font-size: 0.82rem; color: var(--muted-foreground); line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* ============ WIDGETS ============ */
.widget { margin-bottom: 16px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.widget:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }
.widget h3, .widget h2 { margin: 0 0 12px; font-family: 'Noto Sans Bengali', sans-serif; font-size: 1rem; font-weight: 800; }
.Label a, .PopularPosts .item-title a, .LinkList a {
  display: inline-flex; margin: 0 6px 6px 0; padding: 6px 12px;
  background: var(--muted); border-radius: 999px; color: var(--foreground);
  font-size: 0.85rem; transition: all .2s;
}
.Label a:hover, .PopularPosts .item-title a:hover, .LinkList a:hover {
  background: var(--primary-light); color: var(--primary); text-decoration: none;
}

/* ============ WEBSITE LINKS DIRECTORY ============ */
.wlinks-section { margin-top: 24px; }
.wlinks-cat-header {
  background: var(--primary);
  color: white;
  text-align: center;
  padding: 10px 16px;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 800;
  font-size: 0.95rem;
}
.wlinks-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  overflow: hidden;
  background: var(--card);
}
.wlinks-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px 12px;
  border-bottom: 1px solid var(--border);
  text-decoration: none;
  color: var(--foreground);
  transition: background .2s;
  text-align: center;
}
.wlinks-item:nth-child(odd) { border-right: 1px solid var(--border); }
.wlinks-item:hover { background: var(--muted); }
.wlinks-item img { max-height: 40px; max-width: 160px; object-fit: contain; }
.wlinks-item span { font-size: 0.88rem; font-weight: 500; }
.wlinks-submit {
  max-width: 480px;
  margin: 24px auto;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
}
.wlinks-submit h3 { font-family: 'Noto Sans Bengali', sans-serif; font-weight: 800; margin-bottom: 12px; }
.wlinks-submit input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  margin-bottom: 8px;
  font-size: 0.9rem;
  background: var(--background);
}
.wlinks-submit button {
  width: 100%;
  padding: 10px;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
}
.wlinks-submit button:hover { opacity: 0.9; }

/* ============ FOOTER ============ */
.footer-shell { margin: 0 0 24px; }
.footer-card {
  padding: 22px;
  background: var(--header-bg);
  color: var(--header-foreground);
  border-radius: calc(var(--radius) + 4px);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.footer-card a { color: rgba(255,255,255,0.92); }
.copyright { color: rgba(255,255,255,0.68); font-size: 0.88rem; margin-top: 10px; }

/* ============ ANIMATIONS ============ */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-fade-in { animation: fadeInUp .4s ease-out both; }

/* ============ BACK TO TOP ============ */
.back-to-top {
  position: fixed; bottom: 24px; right: 24px;
  width: 42px; height: 42px; border-radius: 999px;
  background: var(--primary); color: white;
  border: none; font-size: 1.1rem; cursor: pointer;
  box-shadow: var(--shadow); display: none;
  align-items: center; justify-content: center; z-index: 99;
}

/* ============ MOBILE SIDEBAR TABS ============ */
.mobile-sidebar-tabs {
  display: none;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  margin-top: 20px;
}
.mobile-tab-bar { display: flex; border-bottom: 1px solid var(--border); }
.mobile-tab-btn {
  flex: 1;
  padding: 10px;
  font-family: 'Noto Sans Bengali', sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
  text-align: center;
  border: none;
  cursor: pointer;
  background: none;
  color: var(--muted-foreground);
  transition: all .2s;
}
.mobile-tab-btn.active { background: var(--primary); color: white; }
.mobile-tab-content { padding: 12px; }

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .three-col { grid-template-columns: 1fr; }
  .left-sidebar, .right-sidebar { display: none; }
  .mobile-sidebar-tabs { display: block; }
  .masonry-grid { columns: 3; }
  .mega-menu-letters { display: none; }
}
@media (max-width: 768px) {
  .masonry-grid { columns: 2; }
  .quick-search { display: none; }
  .mega-cat-grid { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); }
}
@media (max-width: 640px) {
  .container { width: min(100% - 16px, 1180px); }
  .topbar-inner { padding: 12px 0; }
  .masonry-grid { columns: 1; }
  .share-bar { flex-wrap: wrap; }
  .share-btn-bookmark { margin-left: 0; width: 100%; justify-content: center; margin-top: 4px; }
  .nav-bar { overflow-x: auto; flex-wrap: nowrap; -webkit-overflow-scrolling: touch; }
  .nav-btn, .nav-link { flex-shrink: 0; }
  .bcard-grid { grid-template-columns: 1fr; }
}

body.script:
//
var BLOG_URL = window.location.origin;
var banglaLetters = ['অ','আ','ই','উ','এ','ও','ক','খ','গ','ঘ','চ','জ','ট','ড','ঢ','ত','দ','ন','প','ফ','ব','ভ','ম','য','র','ল','শ','স','হ'];

// ==================== MEGA MENU ====================
var currentMega = null;
var megaData = { news: [], blog: [], directory: [] };

function toggleMega(type) {
  if (currentMega === type) { closeMega(); return; }
  closeMega();
  currentMega = type;
  document.getElementById('mega-' + type).classList.add('open');
  document.getElementById('megaOverlay').classList.add('open');
  document.querySelectorAll('.nav-btn').forEach(function(b) {
    b.classList.toggle('active', b.getAttribute('data-menu') === type);
  });
  var input = document.getElementById('search-' + type);
  if (input) input.focus();
  loadMegaData(type);
}

function closeMega() {
  if (!currentMega) return;
  document.getElementById('mega-' + currentMega).classList.remove('open');
  document.getElementById('megaOverlay').classList.remove('open');
  document.querySelectorAll('.nav-btn').forEach(function(b) { b.classList.remove('active'); });
  currentMega = null;
}

function loadMegaData(type) {
  if (megaData[type].length > 0) { renderMega(type); return; }
  // Use Blogger labels feed to populate categories
  fetch(BLOG_URL + '/feeds/posts/default?alt=json&max-results=500')
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var entries = (data.feed && data.feed.entry) || [];
      var labelMap = {};
      entries.forEach(function(entry) {
        (entry.category || []).forEach(function(c) {
          var name = c.term;
          if (!labelMap[name]) labelMap[name] = { name: name, count: 0 };
          labelMap[name].count++;
        });
      });
      var all = Object.values(labelMap);
      // Distribute to types based on keywords (simple heuristic)
      var newsKeywords = ['জনপদ','খবর','সংবাদ','প্রশাসন','শিক্ষা','স্বাস্থ্য','রাজনীতি','অপরাধ','দুর্ঘটনা','আবহাওয়া'];
      var blogKeywords = ['ব্লগ','মতামত','গল্প','কবিতা','ইতিহাস','সংস্কৃতি','ভ্রমণ','রান্না','প্রযুক্তি'];
      var dirKeywords = ['ডিরেক্টরি','ব্যবসা','হাসপাতাল','স্কুল','কলেজ','ব্যাংক','হোটেল','দোকান'];

      all.forEach(function(item) {
        var matched = false;
        newsKeywords.forEach(function(k) { if (item.name.indexOf(k) > -1) { megaData.news.push(item); matched = true; } });
        if (!matched) blogKeywords.forEach(function(k) { if (item.name.indexOf(k) > -1) { megaData.blog.push(item); matched = true; } });
        if (!matched) dirKeywords.forEach(function(k) { if (item.name.indexOf(k) > -1) { megaData.directory.push(item); matched = true; } });
        if (!matched) megaData.news.push(item); // default to news
      });
      renderMega(type);
    })
    .catch(function() { renderMega(type); });
}

function renderMega(type) {
  var items = megaData[type] || [];
  var search = (document.getElementById('search-' + type) || {}).value || '';
  var filtered = search ? items.filter(function(i) { return i.name.indexOf(search) > -1; }) : items;

  // Group by first letter
  var groups = {};
  filtered.forEach(function(item) {
    var letter = item.name[0];
    if (!groups[letter]) groups[letter] = [];
    groups[letter].push(item);
  });

  // Render letter nav
  var letterHtml = '';
  banglaLetters.forEach(function(l) {
    var exists = !!groups[l];
    letterHtml += '<button class="mega-letter-btn' + (exists ? '' : ' disabled') + '" onclick="' + (exists ? 'scrollToMegaLetter(\'' + type + '\',\'' + l + '\')' : '') + '">' + l + '</button>';
  });
  document.getElementById('letters-' + type).innerHTML = letterHtml;

  // Render grid
  var gridHtml = '';
  var colorClass = type === 'news' ? 'news' : type === 'blog' ? 'blog' : 'directory';
  var sortedLetters = Object.keys(groups).sort();
  sortedLetters.forEach(function(letter) {
    gridHtml += '<div id="mega-letter-' + type + '-' + letter + '">';
    gridHtml += '<span class="mega-cat-group-letter ' + colorClass + '">' + letter + '</span>';
    gridHtml += '<div>';
    groups[letter].forEach(function(item) {
      gridHtml += '<a class="mega-cat-link" href="' + BLOG_URL + '/search/label/' + encodeURIComponent(item.name) + '">' + item.name + '</a>';
    });
    gridHtml += '</div></div>';
  });

  if (!gridHtml) gridHtml = '<p style="color:var(--muted-foreground);padding:20px;text-align:center;">কোনো ক্যাটাগরি পাওয়া যায়নি</p>';
  document.getElementById('grid-' + type).innerHTML = gridHtml;
}

function filterMega(type) { renderMega(type); }

function scrollToMegaLetter(type, letter) {
  var el = document.getElementById('mega-letter-' + type + '-' + letter);
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ==================== LEFT SIDEBAR (Tabbed Posts) ====================
var currentSidebarTab = 'latest';

function switchTab(tab) {
  currentSidebarTab = tab;
  document.querySelectorAll('.sidebar-tab').forEach(function(b) {
    b.classList.toggle('active', b.getAttribute('data-tab') === tab);
  });
  loadSidebarPosts(tab);
}

function loadSidebarPosts(tab) {
  var url = BLOG_URL + '/feeds/posts/default?alt=json&max-results=10';
  if (tab === 'news') url += '&category=%E0%A6%9C%E0%A6%A8%E0%A6%AA%E0%A6%A6';
  else if (tab === 'blog') url += '&category=%E0%A6%AC%E0%A7%8D%E0%A6%B2%E0%A6%97';

  fetch(url)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var entries = (data.feed && data.feed.entry) || [];
      if (!entries.length) {
        document.getElementById('sidebar-post-list').innerHTML = '<p class="sidebar-empty">কোনো পোস্ট নেই</p>';
        return;
      }
      var html = '<div class="sidebar-post-list">';
      entries.forEach(function(entry, i) {
        var title = entry.title.$t || '';
        var link = '';
        (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
        var labels = (entry.category || []).map(function(c) { return c.term; });
        var tagHtml = '';
        if (labels.length) {
          var cls = 'tag-news';
          if (labels.indexOf('ব্লগ') > -1) cls = 'tag-blog';
          else if (labels.indexOf('ডিরেক্টরি') > -1) cls = 'tag-directory';
          tagHtml = '<span class="' + cls + '" style="margin-top:4px;display:inline-block;">' + labels[0] + '</span>';
        }
        html += '<a class="sidebar-post-item" href="' + link + '">';
        html += '<span class="sidebar-post-num">' + String(i + 1).padStart(2, '0') + '</span>';
        html += '<div><div class="sidebar-post-title">' + title + '</div>' + tagHtml + '</div>';
        html += '</a>';
      });
      html += '</div>';
      document.getElementById('sidebar-post-list').innerHTML = html;
    })
    .catch(function() {
      document.getElementById('sidebar-post-list').innerHTML = '<p class="sidebar-empty">লোড করা যায়নি</p>';
    });
}

// ==================== HERO SLIDER ====================
var heroSlideIndex = 0;
var heroSlides = [];

function loadHeroSlider() {
  fetch(BLOG_URL + '/feeds/posts/default?alt=json&max-results=5')
    .then(function(r) { return r.json(); })
    .then(function(data) {
      heroSlides = (data.feed && data.feed.entry) || [];
      if (!heroSlides.length) return;
      var sliderHtml = '';
      var dotsHtml = '';
      heroSlides.forEach(function(entry, i) {
        var title = entry.title.$t || '';
        var link = '';
        (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
        var snippet = '';
        if (entry.summary) snippet = entry.summary.$t || '';
        else if (entry.content) snippet = entry.content.$t.replace(/<[^>]+>/g, '').slice(0, 150);
        var labels = (entry.category || []).map(function(c) { return c.term; });
        var kickerLabel = labels.length ? labels[0] : 'গলাচিপা';

        sliderHtml += '<div class="hero-slide' + (i === 0 ? ' active' : '') + '">';
        sliderHtml += '<div class="hero-kicker">🔔 ' + kickerLabel + '</div>';
        sliderHtml += '<h3><a href="' + link + '">' + title + '</a></h3>';
        sliderHtml += '<p>' + snippet + '</p>';
        sliderHtml += '</div>';

        dotsHtml += '<button class="hero-dot' + (i === 0 ? ' active' : '') + '" onclick="goToSlide(' + i + ')"></button>';
      });
      document.getElementById('heroSliderInner').innerHTML = sliderHtml;
      document.getElementById('heroDots').innerHTML = dotsHtml;

      // Auto-play
      setInterval(function() {
        heroSlideIndex = (heroSlideIndex + 1) % heroSlides.length;
        goToSlide(heroSlideIndex);
      }, 5000);
    })
    .catch(function() {});
}

function goToSlide(idx) {
  heroSlideIndex = idx;
  document.querySelectorAll('.hero-slide').forEach(function(s, i) {
    s.classList.toggle('active', i === idx);
  });
  document.querySelectorAll('.hero-dot').forEach(function(d, i) {
    d.classList.toggle('active', i === idx);
  });
}

// ==================== BUSINESS CARDS ====================
function loadBusinessCards() {
  // Load from Blogger pages or static data
  // For now, show placeholder cards from labels
  fetch(BLOG_URL + '/feeds/posts/default?alt=json&max-results=100&category=%E0%A6%A1%E0%A6%BF%E0%A6%B0%E0%A7%87%E0%A6%95%E0%A7%8D%E0%A6%9F%E0%A6%B0%E0%A6%BF')
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var entries = (data.feed && data.feed.entry) || [];
      if (!entries.length) {
        document.getElementById('bcardSection').style.display = 'none';
        return;
      }
      var html = '';
      entries.slice(0, 6).forEach(function(entry) {
        var title = entry.title.$t || '';
        var link = '';
        (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
        var snippet = '';
        if (entry.summary) snippet = entry.summary.$t || '';
        else if (entry.content) snippet = entry.content.$t.replace(/<[^>]+>/g, '').slice(0, 100);

        html += '<a href="' + link + '" class="bcard-item" style="text-decoration:none;color:inherit;">';
        html += '<div class="bcard-name">' + title + '</div>';
        html += '<div class="bcard-info"><span>' + snippet + '</span></div>';
        html += '</a>';
      });
      document.getElementById('bcardGrid').innerHTML = html;
    })
    .catch(function() {
      document.getElementById('bcardSection').style.display = 'none';
    });
}

// ==================== MOBILE SIDEBAR TABS ====================
function switchMobileTab(tab) {
  document.querySelectorAll('.mobile-tab-btn').forEach(function(b, i) {
    b.classList.toggle('active', (tab === 'left' && i === 0) || (tab === 'right' && i === 1));
  });
  var content = document.getElementById('mobileTabContent');
  if (tab === 'left') {
    // Clone left sidebar content
    var leftContent = document.getElementById('sidebar-post-list');
    content.innerHTML = leftContent ? leftContent.innerHTML : '<p class="sidebar-empty">লোড হচ্ছে...</p>';
  } else {
    // Show widgets from right sidebar
    var rightWidgets = document.querySelector('.right-sidebar .sidebar-card');
    content.innerHTML = rightWidgets ? rightWidgets.innerHTML : '<p class="sidebar-empty">কোনো কন্টেন্ট নেই</p>';
  }
}

// ==================== SHARE & BOOKMARK ====================
function copyLink(btn) {
  var url = btn.getAttribute('data-url') || window.location.href;
  navigator.clipboard.writeText(url).then(function() {
    btn.textContent = '✅';
    setTimeout(function() { btn.textContent = '🔗'; }, 1500);
  });
}

function toggleBookmark(btn) {
  var post = btn.closest('.post');
  var title = post ? post.querySelector('.post-title a') : null;
  var url = title ? title.href : window.location.href;
  var key = 'galachipa_bookmarks';
  var bookmarks = JSON.parse(localStorage.getItem(key) || '[]');
  var idx = bookmarks.indexOf(url);
  if (idx > -1) {
    bookmarks.splice(idx, 1);
    btn.textContent = '🔖 বুকমার্ক';
    btn.style.background = '';
    btn.style.color = '';
  } else {
    bookmarks.push(url);
    btn.textContent = '✅ সেভ হয়েছে';
    btn.style.background = 'var(--primary-light)';
    btn.style.color = 'var(--primary)';
  }
  localStorage.setItem(key, JSON.stringify(bookmarks));
}

// Restore bookmark state
document.addEventListener('DOMContentLoaded', function() {
  var bookmarks = JSON.parse(localStorage.getItem('galachipa_bookmarks') || '[]');
  document.querySelectorAll('.share-btn-bookmark').forEach(function(btn) {
    var post = btn.closest('.post');
    var title = post ? post.querySelector('.post-title a') : null;
    var url = title ? title.href : '';
    if (bookmarks.indexOf(url) > -1) {
      btn.textContent = '✅ সেভ হয়েছে';
      btn.style.background = 'var(--primary-light)';
      btn.style.color = 'var(--primary)';
    }
  });
});

// ==================== BACK TO TOP ====================
window.addEventListener('scroll', function() {
  var btn = document.getElementById('backToTop');
  if (btn) btn.style.display = window.scrollY > 400 ? 'flex' : 'none';
});

// ==================== MASONRY GRID ====================
(function() {
  var masonryEl = document.getElementById('masonry-section');
  if (!masonryEl) return;
  fetch(BLOG_URL + '/feeds/posts/default?alt=json&max-results=20')
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var entries = (data.feed && data.feed.entry) || [];
      if (!entries.length) return;
      var grid = document.createElement('div');
      grid.className = 'masonry-grid';
      var ratios = ['56.25%', '75%', '100%', '66.66%'];
      entries.forEach(function(entry, i) {
        var title = entry.title.$t || '';
        var link = '';
        (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
        var img = '';
        if (entry.media$thumbnail) img = entry.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/s600/');
        var snippet = '';
        if (entry.summary) snippet = entry.summary.$t || '';
        else if (entry.content) snippet = entry.content.$t.replace(/<[^>]+>/g, '').slice(0, 120);
        var labels = (entry.category || []).map(function(c) { return c.term; });
        var tagClass = 'tag-news';
        if (labels.indexOf('ব্লগ') > -1) tagClass = 'tag-blog';
        else if (labels.indexOf('ডিরেক্টরি') > -1) tagClass = 'tag-directory';
        var item = document.createElement('div');
        item.className = 'masonry-item animate-fade-in';
        item.style.animationDelay = (i * 50) + 'ms';
        var html = '';
        if (img) {
          var ratio = ratios[i % ratios.length];
          html += '<a href="' + link + '" style="display:block;position:relative;padding-bottom:' + ratio + ';overflow:hidden;">';
          html += '<img src="' + img + '" alt="' + title + '" loading="lazy" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:0;"/>';
          html += '</a>';
        }
        html += '<div class="masonry-item-content">';
        if (labels.length) html += '<span class="' + tagClass + '" style="margin-bottom:6px;">' + labels[0] + '</span> ';
        html += '<div class="masonry-item-title"><a href="' + link + '">' + title + '</a></div>';
        if (snippet) html += '<p class="masonry-item-excerpt">' + snippet + '</p>';
        html += '</div>';
        item.innerHTML = html;
        grid.appendChild(item);
      });
      masonryEl.appendChild(grid);
    })
    .catch(function(err) { console.log('Masonry feed error:', err); });
})();

// ==================== INIT ====================
document.addEventListener('DOMContentLoaded', function() {
  loadSidebarPosts('latest');
  loadHeroSlider();
  loadBusinessCards();
  switchMobileTab('left');
});
//
